export const WING_LEVELS=[10,25,50,75,100,125,150,175,215,250];
export const AURA_LEVELS=[20,35,60,85,110,135,160,185,225,250];
export const STYLES={void:{name:'Vazio Estelar',color:'#df87ff'},infernal:{name:'Coroa Rubra',color:'#ff6979'},solar:{name:'Solar',color:'#f4cb7c'},glacial:{name:'Glacial',color:'#8edcf4'},eclipse:{name:'Eclipse',color:'#c5a2ff'},carmim:{name:'Carmim',color:'#f09ca5'}};
export function initAscension(p){p.wings||={rank:0,style:p.classId==='ARC'?'glacial':p.classId==='ESP'||p.classId==='LAS'?'eclipse':'solar',visible:true};p.aura||={rank:0,style:p.classId==='RUP'?'carmim':p.classId==='ARC'?'glacial':'solar',visible:true};p.materials||={};p.wallet||={cash:0};p.appearances||=[];p.regionClears||={};p.pvpWins||=0;p.pvpLosses||=0;p.heroId||='hero-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
export function ascensionForm(kind,rank){if(!rank)return 'Adormecida';const names=kind==='wings'?['Plumas do Despertar','Cristal Celeste','Lâminas do Firmamento','Arcanjo da Ruptura','Asas Primordiais']:['Centelha Interior','Círculo da Essência','Ressonância Astral','Domínio Celestial','Aura da Origem'];return names[rank<3?0:rank<5?1:rank<8?2:rank<10?3:4];}
export function ascensionCost(p,kind){const r=p[kind]?.rank||0;return {rank:r+1,level:(kind==='wings'?WING_LEVELS:AURA_LEVELS)[r]||250,gold:Math.round(500*(r+1)**2),material:kind==='wings'?'Pluma Astral':'Essência de Aura',count:[5,10,20,35,55,80,115,160,230,320][r]||0,cores:r>=7?(r-6)*2:0};}
export function evolveAscension(p,kind){initAscension(p);if(!['wings','aura'].includes(kind))return {ok:false,reason:'Evolução inválida.'};if(p[kind].rank>=10)return {ok:false,reason:'Evolução máxima.'};const c=ascensionCost(p,kind);if(p.level<c.level)return {ok:false,reason:'Requer nível '+c.level+'.'};if(p.gold<c.gold||(p.materials[c.material]||0)<c.count||(p.materials['Núcleo de Cataclismo']||0)<c.cores)return {ok:false,reason:'Faltam ouro ou materiais. Veja as fontes nesta janela.'};p.gold-=c.gold;p.materials[c.material]-=c.count;if(c.cores)p.materials['Núcleo de Cataclismo']-=c.cores;p[kind].rank++;return {ok:true,rank:p[kind].rank};}
export function ascensionBonuses(p){const w=p.wings?.rank||0,a=p.aura?.rank||0;return {attackPct:w*.012,accuracy:w*20,hpPct:a*.008,defensePct:a*.012,critd:a*.005};}
export function regionAccess(p,index,regions,power=Infinity){if(p.testMode)return {ok:true,reason:'Laboratório: acesso de teste.'};const region=regions[index];if(!region)return {ok:false,reason:'Região inválida.'};if(p.level<region.range[0])return {ok:false,reason:'Requer nível '+region.range[0]+'.'};const minimumPower=Math.round(1200*(1+region.range[0]/35)**1.2);if(index>0&&power<minimumPower)return {ok:false,reason:'Requer poder '+minimumPower.toLocaleString('pt-BR')+'.'};if(index>0&&!(p.regionClears?.[index-1]>0))return {ok:false,reason:'Conclua uma DG da região anterior: '+regions[index-1].name+'.'};if(index===1&&p.quest<4)return {ok:false,reason:'Conclua o capítulo do farol.'};return {ok:true,reason:'Acesso liberado.'};}
export const CASH_PRODUCTS=[{id:'w-eclipse',name:'Asas do Eclipse Rubro',kind:'appearance',price:300,style:'infernal',target:'wings',description:'Traços carmim nas asas. Aparência, sem bônus de poder.'},{id:'a-eclipse',name:'Aura do Vazio Violeta',kind:'appearance',price:220,style:'void',target:'aura',description:'Energia violeta e órbitas arcanas. Aparência, sem bônus de poder.'},{id:'feathers',name:'Suprimento de Plumas',kind:'material',price:120,material:'Pluma Astral',count:30,description:'30 plumas. Também obtidas em caça e DGs.'},{id:'essence',name:'Suprimento de Essência',kind:'material',price:120,material:'Essência de Aura',count:30,description:'30 essências. Também obtidas em caça e DGs.'}];
export function buyCashProduct(p,id){initAscension(p);const item=CASH_PRODUCTS.find(x=>x.id===id);if(!item)return {ok:false,reason:'Produto inexistente.'};if((p.wallet.cash||0)<item.price)return {ok:false,reason:'Cash insuficiente. Ouro e cash são moedas separadas.'};if(item.kind==='appearance'&&p.appearances.includes(id))return {ok:false,reason:'Aparência já adquirida.'};p.wallet.cash-=item.price;if(item.kind==='material')p.materials[item.material]=(p.materials[item.material]||0)+item.count;else {p.appearances.push(id);p[item.target].style=item.style;}return {ok:true};}
export function recordHero(rows,p,power){if(p.testMode)return rows;const entry={id:p.heroId,name:p.name,classId:p.classId,level:p.level,power,wins:p.pvpWins||0,losses:p.pvpLosses||0,updatedAt:Date.now()};return [...rows.filter(r=>r.id!==entry.id),entry].slice(-100);}
export function rankHeroes(rows,type='power'){return rows.slice().sort((a,b)=>type==='pvp'?b.wins-a.wins||a.losses-b.losses||b.power-a.power:b.power-a.power||b.level-a.level);}
